content.text:
{
  "name": "数字微镜图案投影器",
  "name_en": "DLP Light Pattern Projector",
  "manufacturer": "Texas Instruments",
  "description": "这是一种基于数字微镜器件（DLP/DMD）的可编程光图案投影设备，可通过红绿蓝发光二极管与微镜阵列输出静态图像、掩模、线条、光斑及时序图案。在实验室中常用于结构光照明、掩模投影、扫描照明、系统标定和显微成像中的图案化激发。",
  "description_en": "This is a programmable light pattern projector based on a digital micromirror device (DLP/DMD). Using RGB LEDs and a micromirror array, it can project static images, masks, lines, spots, and timed pattern sequences. In the lab it is commonly used for structured illumination, mask projection, scanning illumination, system calibration, and patterned excitation in microscopy.",
  "tag_hints": [
    "DLP projection",
    "digital micromirror device",
    "structured illumination",
    "pattern projection",
    "microscopy illumination",
    "RGB LED illumination",
    "mask projection",
    "calibration patterns"
  ],
  "actions": [
    {
      "action_name": "auto-Connect",
      "description": "连接图案投影器。",
      "description_en": "Connect to the pattern projector."
    },
    {
      "action_name": "auto-Close",
      "description": "断开与图案投影器的连接。",
      "description_en": "Disconnect from the pattern projector."
    },
    {
      "action_name": "auto-SetDisplayMode",
      "description": "设置投影器的显示模式。",
      "description_en": "Set the projector display mode."
    },
    {
      "action_name": "auto-SetImage",
      "description": "投影指定的静态图像。",
      "description_en": "Project a specified static image."
    },
    {
      "action_name": "auto-SetPatternDefs",
      "description": "定义图案序列及其触发、曝光和播放方式。",
      "description_en": "Define a pattern sequence and its trigger, exposure, and playback settings."
    },
    {
      "action_name": "auto-SetPattern",
      "description": "选择并显示指定索引的图案。",
      "description_en": "Select and display a pattern by index."
    },
    {
      "action_name": "auto-SetTestPattern",
      "description": "显示内置测试图案。",
      "description_en": "Display a built-in test pattern."
    },
    {
      "action_name": "auto-SetMask",
      "description": "以指定强度投影给定掩模图案。",
      "description_en": "Project a supplied mask pattern at the specified intensity."
    },
    {
      "action_name": "auto-SetStoredMask",
      "description": "调用已存储的掩模并按指定强度投影。",
      "description_en": "Recall a stored mask and project it at the specified intensity."
    },
    {
      "action_name": "auto-SetStatic",
      "description": "设置静态投影输出。",
      "description_en": "Set the static projection output."
    },
    {
      "action_name": "auto-StartPatternSeq",
      "description": "启动或停止图案序列播放。",
      "description_en": "Start or stop pattern sequence playback."
    },
    {
      "action_name": "auto-AdvancePatternSeq",
      "description": "将图案序列推进到下一步。",
      "description_en": "Advance the pattern sequence to the next step."
    },
    {
      "action_name": "auto-SetLeds",
      "description": "设置红、绿、蓝发光二极管的输出强度。",
      "description_en": "Set the output intensity of the red, green, and blue LEDs."
    },
    {
      "action_name": "auto-SetSpot",
      "description": "在指定位置投影圆形光斑。",
      "description_en": "Project a circular spot at a specified position."
    },
    {
      "action_name": "auto-SetLineIllumination",
      "description": "投影具有设定周期、相位和角度的线状照明图案。",
      "description_en": "Project a line illumination pattern with defined period, phase, and angle."
    },
    {
      "action_name": "auto-SetScanningVDC",
      "description": "设置扫描式占空比线条照明序列。",
      "description_en": "Set a scanning duty-cycle line illumination sequence."
    },
    {
      "action_name": "auto-SetCalibrationPattern",
      "description": "显示用于系统校准的图案。",
      "description_en": "Display a pattern for system calibration."
    },
    {
      "action_name": "auto-SetScanningHex",
      "description": "设置扫描式六角图案照明序列。",
      "description_en": "Set a scanning hexagonal pattern illumination sequence."
    },
    {
      "action_name": "auto-SetVDCLines",
      "description": "投影具有设定周期、相位、角度和占空比的线条图案。",
      "description_en": "Project a line pattern with defined period, phase, angle, and duty cycle."
    },
    {
      "action_name": "auto-GenVDCLines",
      "description": "生成占空比线条图案。",
      "description_en": "Generate a duty-cycle line pattern."
    },
    {
      "action_name": "auto-GenHex",
      "description": "生成六角图案。",
      "description_en": "Generate a hexagonal pattern."
    },
    {
      "action_name": "auto-GenStartMetadata",
      "description": "生成投影开始时的实验元数据。",
      "description_en": "Generate experiment metadata for the start of projection."
    }
  ]
}

